import {S,T,P,B,assemble} from './emc-content.mjs';
export const emc5=assemble([
 S('Transacciones y conjuntos de elementos','Representar una cesta','5.1;5.5.1','137–140;143–146','Las reglas de asociación describen coocurrencias de elementos en unidades llamadas transacciones.',[
 ['Elegir la transacción','Una cesta, una sesión o un intervalo temporal definen unidades diferentes. Repetir el mismo elemento dentro de una transacción no aumenta el soporte de un conjunto binario; si importan cantidades se requiere otra representación.',''],
 ['Definir soporte','El soporte es la proporción de transacciones que contienen todos los elementos del conjunto. La transacción vacía cuenta en el denominador si pertenece a la población estudiada.',T`\operatorname{sup}(A)=\frac1n\sum_{i=1}^n\mathbf1\{A\subseteq T_i\}.`],
 ['Fijar el significado de una regla','A→B compara conjuntos disjuntos, pero la flecha no implica orden temporal ni causa. Si la unidad es una cesta completa, los elementos solo están registrados juntos.','']
 ],P('Las doce cestas sintéticas del laboratorio usan A, B, C y D. A aparece en ocho y B en ocho; A y B aparecen juntos en cinco. Su soporte conjunto es 5/12. Los símbolos son categorías de ejemplo y no datos de la tienda del libro. El control cambia el conjunto buscado y muestra los recuentos que lo contienen.'),[
 ['El soporte de un conjunto cuenta…','Transacciones que contienen todos sus elementos','Solo el número de letras','La suma de repeticiones dentro de una cesta','La definición usa un indicador por transacción.'],['La flecha de una regla implica…','Una dirección condicional, sin causalidad automática','Una intervención probada','Un orden temporal obligatorio','Una coocurrencia en la misma unidad no identifica qué elemento causa otro.'],['Cambiar qué se llama transacción puede…','Cambiar los soportes','No afectar nunca','Hacer todas las reglas ciertas','Agrupar o separar sesiones altera qué eventos se consideran conjuntos.']]),
 S('Soporte, confianza y lift','Tres medidas distintas','5.2–5.3','140–143','La confianza de una regla compara la frecuencia conjunta con la del antecedente; el lift añade la frecuencia del consecuente.',[
 ['Condicionar al antecedente','Si A tiene soporte positivo, la confianza estima P(B dado A). Invertir la flecha cambia el denominador y puede cambiar mucho la confianza.',T`\operatorname{conf}(A\to B)=\frac{\operatorname{sup}(A\cup B)}{\operatorname{sup}(A)}.`],
 ['Comparar con la referencia','El lift divide la confianza por la frecuencia marginal de B. Bajo independencia poblacional y soportes no nulos vale uno; estimaciones muestrales cercanas a uno no prueban independencia.',T`\operatorname{lift}(A\to B)=\frac{\operatorname{sup}(A\cup B)}{\operatorname{sup}(A)\operatorname{sup}(B)}.`],
 ['Evitar reglas triviales','Si B es muy frecuente, puede haber confianza alta incluso sin asociación. Examina soporte, lift y estabilidad fuera de la selección. Ninguna de las tres medidas certifica relevancia ni causalidad por sí sola.','']
 ],P('Con 100 transacciones, A en 20, B en 80 y ambos en 16, confianza(A→B)=0,8. Sin embargo lift=16/100 dividido por 0,2×0,8=1: la confianza coincide con la frecuencia de B. El laboratorio permite construir tablas 2×2 válidas mediante tasas condicionales y compara las tres medidas.'),[
 ['Confianza(A→B) estima…','P(B dado A)','P(A dado B) necesariamente','El efecto causal de A','El denominador restringe el universo a transacciones que contienen el antecedente.'],['Lift uno significa…','Coincidencia con la referencia de independencia en esa tabla','Causalidad perfecta','Confianza uno siempre','El soporte conjunto iguala el producto de los soportes marginales.'],['Una confianza alta puede deberse a…','Un consecuente muy frecuente','Un denominador siempre cero','Que todas las reglas sean temporales','La frecuencia marginal alta puede explicar por sí sola gran parte de la confianza.']]),
 S('Leverage y conviction','Magnitud y excepciones','5.3 y ampliación','141–143','Medidas diferentes destacan aspectos distintos de la misma tabla y conviene conocer sus casos límite.',[
 ['Diferencia absoluta frente a razón','Leverage compara la frecuencia conjunta con la esperada bajo independencia. A diferencia de lift, está en escala de proporciones y puede reflejar una desviación absoluta pequeña aunque una razón sea grande.',T`\operatorname{lev}(A\to B)=\operatorname{sup}(A\cup B)-\operatorname{sup}(A)\operatorname{sup}(B).`],
 ['Ponderar las excepciones','Conviction compara la frecuencia marginal de no B con la de no B dado A. Si confianza es uno y B no es universal, no hay excepciones observadas y la razón tiende a infinito.',T`\operatorname{conv}(A\to B)=\frac{1-\operatorname{sup}(B)}{1-\operatorname{conf}(A\to B)}.`],
 ['Tratar indefiniciones','Si A nunca aparece no se estima su confianza. Si B aparece siempre y confianza es uno, conviction es 0/0 y no una evidencia infinita. El laboratorio distingue infinito de no definido.','']
 ],P('Con soportes A=0,5, B=0,4 y conjunto=0,3, confianza es 0,6, lift 1,5, leverage 0,1 y conviction 1,5. Si el conjunto sube hasta 0,4, confianza es 0,8 y conviction 3. El laboratorio usa combinaciones válidas y muestra cómo cambian ambas medidas al variar la tasa condicional.'),[
 ['Leverage se mide en…','Diferencia de proporciones','Número de segundos','Un cociente obligatorio mayor que uno','Resta dos probabilidades de ocurrencia conjunta.'],['Confianza uno con B no universal da conviction…','Infinita por ausencia de excepciones observadas','Siempre cero','Indefinida por falta de antecedente','El denominador se anula y el numerador permanece positivo.'],['Si A no aparece, su confianza es…','No definida en esa muestra','Cero por certeza','Uno por defecto','No hay transacciones con antecedente para estimar la probabilidad condicional.']]),
 S('Apriori y la propiedad antimonótona','Podar candidatos','5.2','140–141','Apriori evita contar muchos conjuntos imposibles de ser frecuentes usando una propiedad de inclusión.',[
 ['Demostrar la poda','Toda transacción que contiene B contiene también cualquier subconjunto A de B. Por tanto el soporte no puede aumentar al añadir elementos.',T`A\subseteq B\quad\Rightarrow\quad\operatorname{sup}(B)\le\operatorname{sup}(A).`],
 ['Aplicar la contraposición','Si un subconjunto no supera el soporte mínimo, ningún superconjunto lo supera. Se conservan los conjuntos frecuentes de tamaño k para generar candidatos de tamaño k+1 cuyos subconjuntos inmediatos también sean frecuentes.',''],
 ['No extender la propiedad a otras métricas','La confianza y el lift no son antimonótonos de esta forma en ambos lados de una regla. La poda por soporte se justifica por inclusión de eventos, no por cualquier puntuación.','']
 ],P('Con soporte mínimo 0,3, D aparece en tres de doce cestas y no es frecuente. Todos los pares y ternas que contengan D pueden descartarse sin contarlos para decidir frecuencia. Aun así, conjuntos de A,B,C pueden sobrevivir. El laboratorio muestra candidatos y frecuentes por nivel, junto al umbral.'),[
 ['Añadir elementos a un conjunto puede…','Mantener o reducir su soporte','Aumentarlo obligatoriamente','Cambiar el número total de transacciones','El evento de contener más elementos está incluido en el de contener menos.'],['Si {A,B} no es frecuente…','Ningún superconjunto suyo lo será con el mismo umbral','{A,B,C} puede tener mayor soporte','Todas las reglas tienen confianza cero','La propiedad permite podar superconjuntos sin medirlos individualmente.'],['La poda de Apriori usa…','Soporte','Cualquier métrica sin demostrarlo','Una relación causal','Su validez procede de una propiedad concreta de inclusión.']]),
 S('Del conjunto frecuente a la regla','Ejecutar el procedimiento','5.5.2–5.5.3','146–157','Buscar conjuntos frecuentes y generar reglas son dos etapas distintas del análisis.',[
 ['Enumerar la estructura','De un conjunto frecuente F se crean antecedentes no vacíos A y consecuentes F sin A. Ambas partes son disjuntas. El número de reglas candidatas crece rápido con el tamaño del conjunto.',''],
 ['Filtrar con condiciones explícitas','Primero soporte y después confianza permiten limitar resultados, pero no garantizan que los hallazgos sean nuevos. Ordenar solo por lift puede promover reglas con denominadores muy pequeños.',T`A\to F\setminus A,\qquad \varnothing\ne A\subsetneq F.`],
 ['Auditar una regla individual','Recuenta antecedente, consecuente, conjunto y total directamente en las cestas. Esta tabla básica es una verificación más transparente que una lista de reglas sin frecuencias.','']
 ],P('Si {A,B,C} es frecuente, genera seis reglas con ambas partes no vacías: tres con un elemento a la izquierda y tres con dos. Todas comparten el soporte conjunto, pero sus confianzas usan denominadores distintos. El laboratorio enumera conjuntos frecuentes de las doce cestas y desglosa una regla elegida.'),[
 ['Las reglas del mismo conjunto F comparten…','El soporte conjunto','La confianza necesariamente','El mismo antecedente','Todas requieren que se observen a la vez los elementos de F.'],['Para tres elementos hay reglas no triviales…','Seis','Tres siempre','Ocho incluyendo solo las válidas','Se excluyen antecedente vacío y antecedente igual al conjunto completo: 2³−2=6.'],['Ordenar por lift únicamente puede favorecer…','Conjuntos raros e inestables','Siempre las reglas mejor validadas','Solo causalidad','Una frecuencia marginal pequeña puede producir una razón grande con pocos casos.']]),
 S('Dirección, umbrales y visualización','Leer una regla completa','5.4–5.5.3','143–157','Una red de reglas representa condicionales; el tamaño y el color necesitan una leyenda que evite confundir medidas.',[
 ['Invertir con Bayes','El soporte conjunto es simétrico y también el lift, pero la confianza cambia al intercambiar antecedente y consecuente salvo que sus soportes coincidan.',T`\operatorname{conf}(A\to B)\operatorname{sup}(A)=\operatorname{conf}(B\to A)\operatorname{sup}(B).`],
 ['Elegir umbrales antes de destacar','Un mínimo de soporte limita rareza, uno de confianza limita excepciones relativas y uno de lift limita asociación respecto a la base. Son decisiones del análisis, no niveles de significación estadística.',''],
 ['Conservar los números','Una flecha más grande puede significar soporte, confianza o lift según la figura. Declara la codificación y facilita inspeccionar la tabla subyacente. No presentes la dirección de la flecha como una secuencia temporal si los datos no la contienen.','']
 ],P('Si A aparece en 10 de 100 cestas, B en 50 y ambos en 8, la confianza de A→B es 0,8 y la de B→A es 0,16; ambos lifts son 1,6. La regla puede parecer fuerte en una dirección y débil en la otra sin contradicción. El laboratorio intercambia las partes y permite comprobar el denominador.'),[
 ['Invertir la regla conserva…','Soporte conjunto y lift','Toda confianza','Una interpretación causal','El numerador conjunto y el producto marginal son simétricos.'],['Un umbral de confianza 0,8 es…','Un filtro descriptivo elegido','Un valor p de 0,2','Un intervalo de confianza del 80 %','No corresponde por definición a un contraste o a cobertura inferencial.'],['Una visualización de reglas necesita…','Una leyenda de tamaños, colores y flechas','Solo flechas sin datos','Omitir frecuencias','Las codificaciones deben vincularse con métricas definidas.']]),
 S('Validar reglas en datos reservados','Medir estabilidad','5.6','157–158','Las reglas seleccionadas por sus métricas necesitan una evaluación que no reutilice la misma búsqueda.',[
 ['Separar selección y evaluación','Descubre reglas en entrenamiento y vuelve a contar exactamente esas reglas en un periodo o muestra reservados. Si vuelves a elegir allí las mejores, has iniciado otra selección.',''],
 ['Cuantificar incertidumbre de una confianza','Para una regla fijada previamente, los éxitos B entre las transacciones con A permiten una proporción binomial bajo independencia. El intervalo de Wilson mantiene límites dentro de [0,1] y funciona mejor que el normal simétrico en ejemplos pequeños.',T`\tilde p=\frac{\hat p+z^2/(2m)}{1+z^2/m},\quad h=\frac{z\sqrt{\hat p(1-\hat p)/m+z^2/(4m^2)}}{1+z^2/m}.`],
 ['Revisar la unidad independiente','Compras repetidas del mismo usuario o periodos solapados pueden ser dependientes. Entonces m transacciones no equivalen a m unidades independientes y la incertidumbre binomial puede ser demasiado pequeña.','']
 ],P('Una regla fijada se observa ocho veces entre diez antecedentes de la prueba. La confianza es 0,8, pero el intervalo de Wilson del 95 % es aproximadamente [0,490;0,943]. Con 80 entre 100 la confianza es igual y el intervalo es más estrecho. El laboratorio compara ambos tamaños sin prometer una corrección de la selección previa.'),[
 ['La muestra reservada sirve para…','Evaluar reglas ya fijadas','Elegir ilimitadamente nuevas reglas y seguir llamándola prueba','Garantizar causalidad','La independencia de la selección ayuda a estimar rendimiento fuera de la búsqueda.'],['Igual confianza con más antecedentes independientes…','Suele dar más precisión','Da el mismo intervalo siempre','Reduce la confianza a cero','La incertidumbre de una proporción disminuye con un denominador informativo mayor.'],['Un intervalo para una regla prefijada corrige toda búsqueda…','No automáticamente','Sí, por usar Wilson','Sí, si se ordena por lift','La selección de muchas reglas es un problema adicional al de estimar una proporción fija.']]),
 S('Diagnóstico: rareza, redundancia y multiplicidad','De la lista al conocimiento','5.7 y ejercicios','158–160','Una lista extensa de reglas necesita depuración y contraste, no solo una ordenación por una puntuación.',[
 ['Rareza e incertidumbre','Una única coocurrencia entre dos elementos raros puede tener lift muy alto. Informa recuentos, tamaño de muestra e incertidumbre antes de destacar una relación.',''],
 ['Redundancia y búsquedas múltiples','Reglas casi idénticas pueden repetir el mismo patrón. Explorar muchos conjuntos incrementa el riesgo de hallazgos fortuitos; una reserva de evaluación, permutaciones y controles de multiplicidad responden preguntas diferentes y deben planificarse.',''],
 ['Del patrón a la explicación','Una asociación puede reflejar promoción común, segmentación o cómo se definió la cesta. La validez temporal y contextual se estudia con datos nuevos. Una recomendación operativa exige evaluar la decisión y sus costes.','']
 ],P('En 1000 transacciones, si A y B aparecen cada uno una vez y es la misma cesta, lift=1000 y soporte=0,001. El número impresiona, pero procede de un solo caso. El laboratorio mantiene uno o pocos casos conjuntos y cambia el tamaño total, mostrando cómo el lift aumenta mientras el soporte disminuye.'),[
 ['Un lift enorme con un caso conjunto…','Puede ser muy inestable','Demuestra una ley universal','Garantiza relevancia operativa','El cociente puede crecer por marginales pequeños aunque apenas haya evidencia observada.'],['Muchas reglas similares pueden ser…','Redundantes','Experimentos independientes siempre','Pruebas causales acumuladas','Compartir transacciones y elementos produce dependencia y repetición del mismo hallazgo.'],['La estabilidad temporal se comprueba con…','Datos de otro periodo comparables','El mismo ranking una y otra vez','Solo el número de reglas','Recontar fuera del periodo de selección evalúa si el patrón persiste.']])
]);
